import javax.swing.*;
import java.awt.*;
class EmployeeModel { String username="admin",password="admin123"; boolean login(String u,String p){return username.equals(u)&&password.equals(p);} boolean changePassword(String oldP,String newP,String confirm){if(!password.equals(oldP)||!newP.equals(confirm))return false;password=newP;return true;} }
class LoginView extends JFrame { JTextField username=new JTextField(); JPasswordField password=new JPasswordField(); JButton login=new JButton("Login"); LoginView(){setTitle("Employee Portal Login");setSize(350,180);setLayout(new GridLayout(3,2,5,5));setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);add(new JLabel("Username:"));add(username);add(new JLabel("Password:"));add(password);add(login);setLocationRelativeTo(null);setVisible(true);} }
class MainView extends JFrame { JMenuItem addEmployee=new JMenuItem("Add Employee"),viewEmployee=new JMenuItem("View Employee"),changePassword=new JMenuItem("Change Password"),logout=new JMenuItem("Logout"),exit=new JMenuItem("Exit Application"); MainView(){setTitle("Employee Management Portal");setSize(500,300);setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);JMenuBar bar=new JMenuBar();JMenu employee=new JMenu("Employee"),tools=new JMenu("Tools"),exitMenu=new JMenu("Exit");employee.add(addEmployee);employee.add(viewEmployee);tools.add(changePassword);exitMenu.add(logout);exitMenu.add(exit);bar.add(employee);bar.add(tools);bar.add(exitMenu);setJMenuBar(bar);setLocationRelativeTo(null);} }
class EmployeeController { EmployeeModel model; LoginView loginView; MainView mainView; EmployeeController(EmployeeModel m){model=m;showLogin();} void showLogin(){loginView=new LoginView();loginView.login.addActionListener(e->login());} void login(){String u=loginView.username.getText(),p=new String(loginView.password.getPassword());if(model.login(u,p)){JOptionPane.showMessageDialog(loginView,"Login successful!");loginView.dispose();showMain();}else JOptionPane.showMessageDialog(loginView,"Invalid username or password.");} void showMain(){mainView=new MainView();mainView.setVisible(true);mainView.addEmployee.addActionListener(e->addEmployee());mainView.viewEmployee.addActionListener(e->JOptionPane.showMessageDialog(mainView,"Use Add Employee to enter employee details."));mainView.changePassword.addActionListener(e->changePassword());mainView.logout.addActionListener(e->{mainView.dispose();showLogin();});mainView.exit.addActionListener(e->System.exit(0));} void addEmployee(){JTextField id=new JTextField(),name=new JTextField(),dept=new JTextField();JPanel p=new JPanel(new GridLayout(3,2));p.add(new JLabel("Employee ID:"));p.add(id);p.add(new JLabel("Employee Name:"));p.add(name);p.add(new JLabel("Department:"));p.add(dept);if(JOptionPane.showConfirmDialog(mainView,p,"Add Employee",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)JOptionPane.showMessageDialog(mainView,"Employee added successfully.");} void changePassword(){JPasswordField oldP=new JPasswordField(),newP=new JPasswordField(),confirmP=new JPasswordField();JPanel p=new JPanel(new GridLayout(3,2));p.add(new JLabel("Old Password:"));p.add(oldP);p.add(new JLabel("New Password:"));p.add(newP);p.add(new JLabel("Confirm Password:"));p.add(confirmP);if(JOptionPane.showConfirmDialog(mainView,p,"Change Password",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){boolean ok=model.changePassword(new String(oldP.getPassword()),new String(newP.getPassword()),new String(confirmP.getPassword()));JOptionPane.showMessageDialog(mainView,ok?"Password changed successfully.":"Invalid old password or passwords do not match.");}} }
public class EmployeeManagementPortal { public static void main(String[] args){SwingUtilities.invokeLater(()->new EmployeeController(new EmployeeModel()));} }